// Fichier généré par tools/build-admin.mjs — ne pas modifier à la main.
export const ADMIN_FILES = {
 "admin.css": {
  "type": "text/css; charset=utf-8",
  "body": ":root {\n  --bg: #0b1310; --panel: #111d18; --panel-2: #16261f; --line: rgba(230, 192, 104, .16);\n  --or: #e6c068; --or-2: #b8862b; --rouge: #c8102e; --vert: #2f8a5b; --texte: #f1eee6; --muted: rgba(241, 238, 230, .6);\n  --sans: system-ui, -apple-system, \"Segoe UI\", Roboto, Arial, sans-serif;\n  --serif: \"Playfair Display\", Georgia, serif;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; font-family: var(--sans); background: var(--bg); color: var(--texte); font-size: 15px; }\n[hidden] { display: none !important; }\na { color: var(--or); }\n.muted { color: var(--muted); }\n\ninput, select, textarea {\n  width: 100%; padding: 10px 12px; border-radius: 10px; font: inherit; color: var(--texte);\n  background: #0a1411; border: 1px solid rgba(255, 255, 255, .12);\n}\ninput:focus, select:focus, textarea:focus { outline: 2px solid var(--or); outline-offset: 0; border-color: transparent; }\ntextarea { resize: vertical; min-height: 90px; }\nlabel { display: grid; gap: 6px; font-size: 13px; font-weight: 600; color: var(--muted); }\ninput[type=checkbox] { width: auto; accent-color: var(--or); transform: scale(1.2); }\n.check { display: flex; align-items: center; gap: 10px; color: var(--texte); font-weight: 500; font-size: 14px; }\n\n.btn-primary, .btn, .btn-danger {\n  border: 0; border-radius: 10px; padding: 10px 18px; font: inherit; font-weight: 700; cursor: pointer;\n  color: #2a1c05; background: linear-gradient(180deg, #fff0bf, var(--or) 50%, var(--or-2));\n}\n.btn { background: var(--panel-2); color: var(--texte); border: 1px solid var(--line); font-weight: 600; }\n.btn-danger { background: rgba(200, 16, 46, .15); color: #ff8b9d; border: 1px solid rgba(200, 16, 46, .4); font-weight: 600; padding: 6px 12px; }\nbutton:disabled { opacity: .6; cursor: wait; }\n\n/* ----- Connexion ----- */\n.login-page { min-height: 100vh; display: grid; place-items: center; padding: 20px;\n  background: radial-gradient(ellipse at top, rgba(230, 192, 104, .12), transparent 60%), var(--bg); }\n.login-card { width: min(380px, 100%); display: grid; gap: 16px; padding: 34px 28px; border-radius: 20px;\n  background: var(--panel); border: 1px solid var(--line); box-shadow: 0 30px 60px rgba(0, 0, 0, .5); }\n.login-card h1 { margin: 0; font-family: var(--serif); color: var(--or); font-size: 26px; }\n.login-card .muted { margin: -10px 0 4px; }\n.login-logo { font-size: 36px; }\n.error { margin: 0; padding: 10px 12px; border-radius: 10px; background: rgba(200, 16, 46, .15); border: 1px solid rgba(200, 16, 46, .4); color: #ffb3bf; font-size: 14px; }\n.back { font-size: 13px; text-align: center; text-decoration: none; color: var(--muted); }\n\n/* ----- Tableau de bord ----- */\n.layout { display: grid; grid-template-columns: 230px 1fr; min-height: 100vh; }\n.side { background: var(--panel); border-right: 1px solid var(--line); padding: 22px 14px; display: flex; flex-direction: column; gap: 4px; position: sticky; top: 0; height: 100vh; }\n.side .brand { font-family: var(--serif); color: var(--or); font-size: 19px; padding: 0 10px 18px; }\n.side button.tab { text-align: left; background: none; border: 0; color: var(--muted); font: inherit; padding: 10px 12px; border-radius: 10px; cursor: pointer; font-weight: 600; }\n.side button.tab:hover { background: var(--panel-2); color: var(--texte); }\n.side button.tab.active { background: rgba(230, 192, 104, .12); color: var(--or); }\n.side .spacer { flex: 1; }\n.side .who { font-size: 12px; color: var(--muted); padding: 0 10px 8px; word-break: break-all; }\n.side a.view { padding: 10px 12px; font-size: 14px; text-decoration: none; }\nmain.content { padding: 28px 32px 60px; max-width: 1200px; width: 100%; min-width: 0; }\nh2 { font-family: var(--serif); margin: 0 0 6px; font-size: 28px; }\nh3 { margin: 0 0 14px; font-size: 16px; }\n.lead { color: var(--muted); margin: 0 0 22px; }\n\n.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 14px; margin-bottom: 24px; }\n.stat { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 16px 18px; }\n.stat span { display: block; font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .08em; }\n.stat strong { display: block; font-size: 30px; margin-top: 6px; color: var(--or); font-variant-numeric: tabular-nums; }\n\n.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 16px; padding: 20px; margin-bottom: 22px; }\n.toolbar { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; margin-bottom: 14px; }\n.toolbar label { min-width: 160px; }\n.table-wrap { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; font-size: 14px; }\nth, td { padding: 10px 10px; text-align: left; border-bottom: 1px solid rgba(255, 255, 255, .06); white-space: nowrap; }\nth { color: var(--muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: .06em; }\ntd.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }\ntr.today td { background: rgba(230, 192, 104, .07); }\n.pill { display: inline-block; padding: 2px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; }\n.pill.oui { background: rgba(230, 192, 104, .18); color: var(--or); }\n.pill.non { background: rgba(255, 255, 255, .06); color: var(--muted); }\n.stat.warn strong { color: #ffd98a; }\n.status { display: inline-block; padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; }\n.status.attente { background: rgba(255, 217, 138, .15); color: #ffd98a; }\n.status.validee { background: rgba(127, 214, 164, .15); color: #8ee0ad; }\n.status.refusee { background: rgba(200, 16, 46, .18); color: #ff9aa9; }\n.row-actions { display: flex; gap: 6px; }\n.btn-ok { border: 1px solid rgba(127, 214, 164, .45); background: rgba(127, 214, 164, .12); color: #8ee0ad; border-radius: 10px; padding: 6px 12px; font: inherit; font-weight: 600; cursor: pointer; }\n.btn-no { border: 1px solid rgba(255, 154, 169, .4); background: rgba(200, 16, 46, .12); color: #ff9aa9; border-radius: 10px; padding: 6px 12px; font: inherit; font-weight: 600; cursor: pointer; }\n.btn-ghost { border: 1px solid rgba(255, 255, 255, .12); background: none; color: var(--muted); border-radius: 10px; padding: 6px 10px; font: inherit; cursor: pointer; }\n.code { font-family: ui-monospace, Menlo, Consolas, monospace; letter-spacing: .04em; }\n.empty { color: var(--muted); text-align: center; padding: 28px; }\n\n.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }\n.form-grid .full { grid-column: 1 / -1; }\n.hint { font-weight: 400; font-size: 12px; color: var(--muted); }\n.actions { display: flex; gap: 10px; align-items: center; margin-top: 18px; }\n.saved { color: #7fd6a4; font-size: 14px; }\n\n.case-list { display: grid; gap: 10px; }\n.case-item { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; overflow: hidden; }\n.case-item summary { cursor: pointer; padding: 14px 18px; display: flex; gap: 14px; align-items: center; list-style: none; }\n.case-item summary::-webkit-details-marker { display: none; }\n.case-item .d { width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; font-weight: 800; color: var(--or); background: #0f3b2b; border: 1px solid rgba(230, 192, 104, .3); flex: none; }\n.case-item .t { flex: 1; min-width: 0; }\n.case-item .t b { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.case-item .t small { color: var(--muted); }\n.case-item[open] summary { border-bottom: 1px solid var(--line); }\n.case-item form { padding: 18px; }\n\n.draw-stage { text-align: center; padding: 30px 20px; border-radius: 16px; margin-top: 16px;\n  background: radial-gradient(circle at center, rgba(230, 192, 104, .14), transparent 70%), #0a1411; border: 1px solid var(--line); }\n.draw-name { font-family: var(--serif); font-size: clamp(30px, 5vw, 52px); color: var(--or); margin: 6px 0; min-height: 1.2em; }\n.draw-name.rolling { color: var(--muted); }\n.draw-meta { color: var(--muted); }\n\n.toast { position: fixed; bottom: 22px; right: 22px; padding: 12px 18px; border-radius: 12px; background: #1b2b24; border: 1px solid var(--line); box-shadow: 0 12px 30px rgba(0, 0, 0, .5); z-index: 10; }\n.toast.err { border-color: rgba(200, 16, 46, .6); color: #ffb3bf; }\n\n@media (max-width: 820px) {\n  .layout { grid-template-columns: 1fr; }\n  .side { position: static; height: auto; flex-direction: row; flex-wrap: wrap; padding: 12px; }\n  .side .brand { width: 100%; padding-bottom: 8px; }\n  .side .spacer { display: none; }\n  main.content { padding: 20px 16px 50px; }\n  .form-grid { grid-template-columns: 1fr; }\n}\n.mt { margin-top: 24px; }\n"
 },
 "admin.html": {
  "type": "text/html; charset=utf-8",
  "body": "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <title>Administration · Calendrier</title>\n  <link rel=\"stylesheet\" href=\"/admin/admin.css\">\n  <script type=\"module\" src=\"/admin/admin.js\"></script>\n</head>\n<body>\n<div class=\"layout\">\n  <nav class=\"side\">\n    <div class=\"brand\">🎄 Administration</div>\n    <button class=\"tab active\" data-tab=\"dashboard\">Tableau de bord</button>\n    <button class=\"tab\" data-tab=\"participants\">Participants & tickets</button>\n    <button class=\"tab\" data-tab=\"draw\">Tirage au sort</button>\n    <button class=\"tab\" data-tab=\"cases\">Cases & lots</button>\n    <button class=\"tab\" data-tab=\"settings\">Réglages</button>\n    <button class=\"tab\" data-tab=\"account\">Compte</button>\n    <div class=\"spacer\"></div>\n    <div class=\"who\" id=\"who\"></div>\n    <a class=\"view\" href=\"/\" target=\"_blank\" rel=\"noopener\">Voir le calendrier ↗</a>\n    <button class=\"tab\" id=\"logout\">Se déconnecter</button>\n  </nav>\n\n  <main class=\"content\">\n    <!-- Tableau de bord -->\n    <section data-panel=\"dashboard\">\n      <h2>Tableau de bord</h2>\n      <p class=\"lead\" id=\"today-line\"></p>\n      <div class=\"cards\">\n        <div class=\"stat\"><span>Visiteurs aujourd’hui</span><strong id=\"s-visitors-today\">–</strong></div>\n        <div class=\"stat\"><span>Visiteurs au total</span><strong id=\"s-visitors\">–</strong></div>\n        <div class=\"stat\"><span>Pages vues</span><strong id=\"s-views\">–</strong></div>\n        <div class=\"stat\"><span>Participants uniques</span><strong id=\"s-participants\">–</strong></div>\n        <div class=\"stat\"><span>Participations</span><strong id=\"s-participations\">–</strong></div>\n        <div class=\"stat\"><span>Tickets distribués</span><strong id=\"s-tickets\">–</strong></div>\n        <div class=\"stat warn\"><span>À valider</span><strong id=\"s-pending\">–</strong></div>\n        <div class=\"stat\"><span>Validées</span><strong id=\"s-validated\">–</strong></div>\n      </div>\n      <div class=\"panel\">\n        <h3>Par jour</h3>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Jour</th><th>Lot</th><th class=\"num\">Ouvertures</th><th class=\"num\">Participants</th><th class=\"num\">À valider</th><th class=\"num\">Validées</th><th class=\"num\">Tickets</th><th>Gagnant</th></tr></thead>\n          <tbody id=\"by-day\"></tbody>\n        </table></div>\n      </div>\n      <div class=\"panel\">\n        <h3>Visites du site</h3>\n        <p class=\"hint\">Visiteurs uniques (par appareil) et nombre de pages vues, par date.</p>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Date</th><th class=\"num\">Visiteurs</th><th class=\"num\">Pages vues</th></tr></thead>\n          <tbody id=\"visits\"></tbody>\n        </table></div>\n      </div>\n    </section>\n\n    <!-- Participants -->\n    <section data-panel=\"participants\" hidden>\n      <h2>Participants & tickets</h2>\n      <p class=\"lead\">Toutes les personnes qui ont activé leur récompense. Vérifie leurs infos sur TikTok, puis valide ou refuse chaque participation. Seules les participations validées comptent pour le tirage.</p>\n      <div class=\"panel\">\n        <div class=\"toolbar\">\n          <label>Jour\n            <select id=\"p-day\"><option value=\"\">Tous les jours</option></select>\n          </label>\n          <label>Statut\n            <select id=\"p-status\">\n              <option value=\"\">Tous</option>\n              <option value=\"attente\">⏳ À valider</option>\n              <option value=\"validee\">✅ Validées</option>\n              <option value=\"refusee\">❌ Refusées</option>\n            </select>\n          </label>\n          <label>Rechercher un pseudo\n            <input id=\"p-search\" placeholder=\"pseudo…\">\n          </label>\n          <button class=\"btn\" id=\"p-refresh\">Actualiser</button>\n          <button class=\"btn\" id=\"p-validate-all\">✅ Tout valider pour ce jour</button>\n          <a class=\"btn\" id=\"p-csv\" href=\"/api/admin/participations.csv\">Exporter (CSV / Excel)</a>\n        </div>\n        <p class=\"hint\" id=\"p-summary\"></p>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Jour</th><th>Pseudo TikTok</th><th class=\"num\">Cœurs du jour</th><th>Top Fan</th><th class=\"num\">Tickets</th><th>Code ticket</th><th>Statut</th><th>Date</th><th>Actions</th></tr></thead>\n          <tbody id=\"p-rows\"></tbody>\n        </table></div>\n      </div>\n    </section>\n\n    <!-- Tirage -->\n    <section data-panel=\"draw\" hidden>\n      <h2>Tirage au sort</h2>\n      <p class=\"lead\">Tire un gagnant parmi les participants d’un jour. Chaque ticket compte comme une chance.</p>\n      <div class=\"panel\">\n        <div class=\"toolbar\">\n          <label>Jour\n            <select id=\"d-day\"></select>\n          </label>\n          <label class=\"check\"><input type=\"checkbox\" id=\"d-validated\" checked> Seulement les participations validées</label>\n          <label class=\"check\"><input type=\"checkbox\" id=\"d-exclude\"> Exclure les gagnants précédents</label>\n          <button class=\"btn-primary\" id=\"d-go\">🎲 Lancer le tirage</button>\n        </div>\n        <div class=\"draw-stage\">\n          <div class=\"muted\" id=\"d-reward\"></div>\n          <div class=\"draw-name\" id=\"d-name\">—</div>\n          <div class=\"draw-meta\" id=\"d-meta\"></div>\n        </div>\n      </div>\n      <div class=\"panel\">\n        <h3>Historique des tirages</h3>\n        <div class=\"table-wrap\"><table>\n          <thead><tr><th>Jour</th><th>Lot</th><th>Gagnant</th><th>Code ticket</th><th>Date</th><th></th></tr></thead>\n          <tbody id=\"d-history\"></tbody>\n        </table></div>\n      </div>\n    </section>\n\n    <!-- Cases -->\n    <section data-panel=\"cases\" hidden>\n      <h2>Cases & lots</h2>\n      <p class=\"lead\">Modifie le contenu de chaque case : titre, message, lot, image et lien.</p>\n      <div class=\"case-list\" id=\"case-list\"></div>\n    </section>\n\n    <!-- Réglages -->\n    <section data-panel=\"settings\" hidden>\n      <h2>Réglages</h2>\n      <p class=\"lead\">Nom du calendrier, dates, participations et règles des tickets.</p>\n      <form class=\"panel\" id=\"settings-form\">\n        <h3>Apparence</h3>\n        <div class=\"form-grid\">\n          <label class=\"full\">Nom du calendrier <input name=\"app_name\" maxlength=\"80\" required></label>\n          <label class=\"full\">Sous-titre <input name=\"subtitle\" maxlength=\"200\"></label>\n          <label class=\"full\">Texte du bas de page <input name=\"footer_text\" maxlength=\"300\"></label>\n        </div>\n        <h3 class=\"mt\">Musique</h3>\n        <div class=\"form-grid\">\n          <label class=\"check full\"><input type=\"checkbox\" name=\"music_enabled\"> Jouer une musique de Noël sur le calendrier</label>\n          <label class=\"full\">Musique\n            <select name=\"music_track\">\n              <option value=\"wewish\">We Wish You a Merry Christmas</option>\n              <option value=\"jingle\">Jingle Bells</option>\n              <option value=\"doucenuit\">Douce nuit</option>\n            </select>\n          </label>\n          <label class=\"full\">Lien d’un fichier MP3 (optionnel) <span class=\"hint\">Remplace la musique choisie au-dessus. Utilise uniquement une musique que tu as le droit de diffuser.</span>\n            <input name=\"music_url\" type=\"url\" placeholder=\"https://…/musique.mp3\"></label>\n        </div>\n        <h3 class=\"mt\">Dates</h3>\n        <div class=\"form-grid\">\n          <label>Année du calendrier <input name=\"year\" type=\"number\" min=\"2024\" max=\"2100\" required></label>\n          <label>Fuseau horaire <input name=\"timezone\" placeholder=\"Europe/Paris\"></label>\n          <label class=\"full\">Date de test <span class=\"hint\">Pour essayer le calendrier avant décembre. Laisse vide pour utiliser la vraie date. ⚠️ Les viewers voient aussi cette date.</span>\n            <input name=\"test_date\" type=\"date\">\n          </label>\n        </div>\n        <h3 class=\"mt\">Participations & tickets</h3>\n        <div class=\"form-grid\">\n          <label class=\"check full\"><input type=\"checkbox\" name=\"participation_open\"> Les viewers peuvent activer leur récompense</label>\n          <label>Tickets par participation <input name=\"tickets_base\" type=\"number\" min=\"1\" max=\"100\"></label>\n          <label>Tickets bonus si Top Fan <input name=\"tickets_topfan_bonus\" type=\"number\" min=\"0\" max=\"100\"></label>\n          <label>+1 ticket tous les … cœurs <span class=\"hint\">0 = désactivé</span><input name=\"tickets_hearts_step\" type=\"number\" min=\"0\"></label>\n          <label>Maximum de tickets par personne <input name=\"tickets_max\" type=\"number\" min=\"1\" max=\"1000\"></label>\n        </div>\n        <div class=\"actions\"><button class=\"btn-primary\" type=\"submit\">Enregistrer</button><span class=\"saved\" id=\"settings-saved\" hidden>Enregistré ✓</span></div>\n      </form>\n    </section>\n\n    <!-- Compte -->\n    <section data-panel=\"account\" hidden>\n      <h2>Compte</h2>\n      <p class=\"lead\">Change le code administrateur. Tu devras te reconnecter ensuite. Ne donne ce code qu’aux personnes de confiance.</p>\n      <form class=\"panel\" id=\"account-form\">\n        <div class=\"form-grid\">\n          <label class=\"full\">Code actuel <input name=\"current_code\" type=\"password\" autocomplete=\"current-password\" required></label>\n          <label>Nouveau code <span class=\"hint\">8 caractères minimum.</span>\n            <input name=\"new_code\" type=\"password\" autocomplete=\"new-password\" required></label>\n          <label>Confirmer le nouveau code <input name=\"confirm\" type=\"password\" autocomplete=\"new-password\" required></label>\n        </div>\n        <div class=\"actions\"><button class=\"btn-primary\" type=\"submit\">Mettre à jour</button></div>\n      </form>\n    </section>\n  </main>\n</div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n</body>\n</html>\n"
 },
 "admin.js": {
  "type": "text/javascript; charset=utf-8",
  "body": "// Tableau de bord administrateur. Toutes les données viennent d'API protégées côté serveur.\nconst $ = (id) => document.getElementById(id);\nlet CSRF = '';\n\nconst ICON_LABELS = {\n  etoile: 'Étoile', boule: 'Boule de Noël', sapin: 'Sapin', cadeau: 'Cadeau', cloche: 'Cloche', 'sucre-orge': 'Sucre d’orge',\n  houx: 'Houx', flocon: 'Flocon', chaussette: 'Chaussette', bougie: 'Bougie', couronne: 'Couronne', bonhomme: 'Bonhomme de neige',\n};\n\n// ---------- Utilitaires ----------\nfunction el(tag, props = {}, ...children) {\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(props)) {\n    if (k === 'class') e.className = v;\n    else if (k === 'text') e.textContent = v;\n    else if (k.startsWith('on')) e.addEventListener(k.slice(2), v);\n    else if (v !== false && v != null) e.setAttribute(k, v === true ? '' : v);\n  }\n  for (const c of children) if (c != null) e.append(c);\n  return e;\n}\n\nasync function api(url, { method = 'GET', body } = {}) {\n  const res = await fetch(url, {\n    method,\n    headers: method === 'GET' ? {} : { 'Content-Type': 'application/json', 'X-CSRF-Token': CSRF },\n    body: body ? JSON.stringify(body) : undefined,\n    cache: 'no-store',\n  });\n  if (res.status === 401) { location.href = '/admin/login'; throw new Error('Session expirée'); }\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new Error(data.error || 'Erreur');\n  return data;\n}\n\nlet toastTimer;\nfunction toast(msg, isErr = false) {\n  const t = $('toast');\n  t.textContent = msg; t.className = `toast${isErr ? ' err' : ''}`; t.hidden = false;\n  clearTimeout(toastTimer); toastTimer = setTimeout(() => { t.hidden = true; }, 3000);\n}\n\nconst fmtDate = (s) => {\n  if (!s) return '';\n  const d = new Date(s.replace(' ', 'T') + 'Z');\n  return d.toLocaleString('fr-FR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });\n};\nconst nf = (n) => Number(n || 0).toLocaleString('fr-FR');\n\n// ---------- Onglets ----------\nconst loaders = {};\ndocument.querySelectorAll('.tab[data-tab]').forEach((b) => b.addEventListener('click', () => showTab(b.dataset.tab)));\nfunction showTab(name) {\n  document.querySelectorAll('.tab[data-tab]').forEach((b) => b.classList.toggle('active', b.dataset.tab === name));\n  document.querySelectorAll('[data-panel]').forEach((p) => { p.hidden = p.dataset.panel !== name; });\n  loaders[name]?.();\n}\n\n// ---------- Tableau de bord ----------\nlet todayDay = null;\nloaders.dashboard = async () => {\n  const s = await api('/api/admin/stats');\n  todayDay = s.today.day;\n  const line = { avant: 'Le calendrier n’a pas encore commencé.', apres: 'Le calendrier est terminé.', pendant: `Aujourd’hui : case n°${s.today.day}.` }[s.today.status];\n  $('today-line').textContent = `${line} Date utilisée : ${s.today.date}${s.today.testMode ? ' (date de test active ⚠️)' : ''}`;\n  $('s-visitors-today').textContent = nf(s.totals.visitorsToday);\n  $('s-visitors').textContent = nf(s.totals.visitors);\n  $('s-views').textContent = nf(s.totals.views);\n  $('s-participants').textContent = nf(s.totals.participants);\n  $('s-participations').textContent = nf(s.totals.participations);\n  $('s-tickets').textContent = nf(s.totals.tickets);\n  $('s-pending').textContent = nf(s.totals.pending);\n  $('s-validated').textContent = nf(s.totals.validated);\n\n  $('by-day').replaceChildren(...s.byDay.map((r) => el('tr', { class: r.day === todayDay ? 'today' : '' },\n    el('td', { text: `${r.day} déc.` }), el('td', { text: r.reward || '—' }),\n    el('td', { class: 'num', text: nf(r.opens) }), el('td', { class: 'num', text: nf(r.participants) }),\n    el('td', { class: 'num', text: nf(r.pending) }), el('td', { class: 'num', text: nf(r.validated) }),\n    el('td', { class: 'num', text: nf(r.tickets) }), el('td', { text: r.winner ? `@${r.winner}` : '—' }))));\n\n  $('visits').replaceChildren(...(s.visitsByDate.length ? s.visitsByDate.map((v) => el('tr', {},\n    el('td', { text: new Date(v.date + 'T12:00:00').toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'long' }) }),\n    el('td', { class: 'num', text: nf(v.visitors) }), el('td', { class: 'num', text: nf(v.views) })))\n    : [el('tr', {}, el('td', { colspan: 3, class: 'empty', text: 'Aucune visite pour le moment.' }))]));\n};\n\n// ---------- Participants ----------\nfunction fillDaySelect(select, withAll) {\n  select.replaceChildren(...(withAll ? [el('option', { value: '', text: 'Tous les jours' })] : []),\n    ...Array.from({ length: 24 }, (_, i) => el('option', { value: i + 1, text: `${i + 1} décembre` })));\n}\nfillDaySelect($('p-day'), true);\nfillDaySelect($('d-day'), false);\n\nlet participations = [];\nloaders.participants = async () => {\n  const q = new URLSearchParams();\n  if ($('p-day').value) q.set('day', $('p-day').value);\n  if ($('p-status').value) q.set('status', $('p-status').value);\n  const data = await api(`/api/admin/participations?${q}`);\n  participations = data.participations;\n  renderParticipants();\n};\nfunction renderParticipants() {\n  const q = $('p-search').value.trim().toLowerCase();\n  const rows = participations.filter((p) => !q || p.pseudo.toLowerCase().includes(q));\n  const tickets = rows.reduce((a, p) => a + p.tickets, 0);\n  const cnt = (st) => rows.filter((p) => p.status === st).length;\n  $('p-summary').textContent = `${nf(rows.length)} participation${rows.length > 1 ? 's' : ''} · ${nf(tickets)} ticket${tickets > 1 ? 's' : ''} · ${nf(rows.filter((p) => p.top_fan).length)} Top Fan · ⏳ ${cnt('attente')} à valider · ✅ ${cnt('validee')} validée(s) · ❌ ${cnt('refusee')} refusée(s)`;\n  $('p-rows').replaceChildren(...(rows.length ? rows.map((p) => el('tr', {},\n    el('td', { text: `${p.day} déc.` }),\n    el('td', {}, el('a', { href: `https://www.tiktok.com/@${encodeURIComponent(p.pseudo)}`, target: '_blank', rel: 'noopener noreferrer', text: `@${p.pseudo}` })),\n    el('td', { class: 'num', text: nf(p.hearts) }),\n    el('td', {}, el('span', { class: `pill ${p.top_fan ? 'oui' : 'non'}`, text: p.top_fan ? 'Oui' : 'Non' })),\n    el('td', { class: 'num', text: p.tickets }),\n    el('td', { class: 'code', text: p.ticket_code }),\n    el('td', {}, el('span', { class: `status ${p.status}`, text: STATUS_LABELS[p.status] || p.status })),\n    el('td', { text: fmtDate(p.created_at) }),\n    el('td', {}, el('div', { class: 'row-actions' },\n      p.status !== 'validee' ? el('button', { class: 'btn-ok', text: 'Valider', onclick: () => setStatus(p, 'validee') }) : null,\n      p.status !== 'refusee' ? el('button', { class: 'btn-no', text: 'Refuser', onclick: () => setStatus(p, 'refusee') }) : null,\n      p.status !== 'attente' ? el('button', { class: 'btn-ghost', text: '↺ En attente', title: 'Remettre en attente', onclick: () => setStatus(p, 'attente') }) : null,\n      el('button', { class: 'btn-danger', text: 'Supprimer', onclick: async () => {\n        if (!confirm(`Supprimer la participation de @${p.pseudo} (jour ${p.day}) ?`)) return;\n        try { await api(`/api/admin/participations/${p.id}`, { method: 'DELETE' }); toast('Participation supprimée'); loaders.participants(); }\n        catch (e) { toast(e.message, true); }\n      } })))))\n    : [el('tr', {}, el('td', { colspan: 9, class: 'empty', text: 'Aucune participation pour le moment.' }))]));\n}\nconst STATUS_LABELS = { attente: '⏳ À valider', validee: '✅ Validée', refusee: '❌ Refusée' };\nasync function setStatus(p, status) {\n  try {\n    await api(`/api/admin/participations/${p.id}`, { method: 'PUT', body: { status } });\n    p.status = status;\n    renderParticipants();\n  } catch (e) { toast(e.message, true); }\n}\n$('p-day').addEventListener('change', () => loaders.participants());\n$('p-status').addEventListener('change', () => loaders.participants());\n$('p-validate-all').addEventListener('click', async () => {\n  const day = $('p-day').value;\n  if (!day) return toast('Choisis d’abord un jour dans la liste « Jour ».', true);\n  if (!confirm(`Valider toutes les participations en attente du ${day} décembre ?`)) return;\n  try {\n    const r = await api('/api/admin/participations/validate-all', { method: 'POST', body: { day: Number(day) } });\n    toast(`${r.changed} participation(s) validée(s)`);\n    loaders.participants();\n  } catch (e) { toast(e.message, true); }\n});\n$('p-search').addEventListener('input', renderParticipants);\n$('p-refresh').addEventListener('click', () => loaders.participants());\n\n// ---------- Tirage au sort ----------\nlet rewards = {};\nloaders.draw = async () => {\n  if (!Object.keys(rewards).length) {\n    const c = await api('/api/admin/cases');\n    c.cases.forEach((x) => { rewards[x.day] = x.reward; });\n  }\n  if (todayDay && !$('d-day').dataset.touched) $('d-day').value = todayDay;\n  $('d-reward').textContent = `Lot : ${rewards[$('d-day').value] || '—'}`;\n  const h = await api('/api/admin/draws');\n  $('d-history').replaceChildren(...(h.draws.length ? h.draws.map((d) => el('tr', {},\n    el('td', { text: `${d.day} déc.` }), el('td', { text: d.reward }), el('td', { text: `@${d.pseudo}` }),\n    el('td', { class: 'code', text: d.ticket_code }), el('td', { text: fmtDate(d.created_at) }),\n    el('td', {}, el('button', { class: 'btn-danger', text: 'Annuler', onclick: async () => {\n      if (!confirm('Annuler ce tirage ?')) return;\n      await api(`/api/admin/draws/${d.id}`, { method: 'DELETE' }); loaders.draw();\n    } }))))\n    : [el('tr', {}, el('td', { colspan: 6, class: 'empty', text: 'Aucun tirage effectué.' }))]));\n};\n$('d-day').addEventListener('change', () => { $('d-day').dataset.touched = '1'; $('d-name').textContent = '—'; $('d-meta').textContent = ''; loaders.draw(); });\n\n$('d-go').addEventListener('click', async () => {\n  const day = $('d-day').value;\n  const btn = $('d-go'); btn.disabled = true;\n  const name = $('d-name');\n  try {\n    const onlyValidated = $('d-validated').checked;\n    const list = (await api(`/api/admin/participations?day=${day}${onlyValidated ? '&status=validee' : ''}`)).participations\n      .filter((p) => p.status !== 'refusee');\n    if (!list.length) throw new Error(onlyValidated ? 'Aucune participation validée pour ce jour. Valide des participations d’abord.' : 'Aucun participant pour ce jour.');\n    // Petite animation de suspense, le vrai tirage est fait par le serveur\n    name.classList.add('rolling');\n    for (let i = 0; i < 22; i++) {\n      name.textContent = `@${list[Math.floor(Math.random() * list.length)].pseudo}`;\n      await new Promise((r) => setTimeout(r, 50 + i * 8));\n    }\n    const r = await api(`/api/admin/draw/${day}`, { method: 'POST', body: { exclude_previous_winners: $('d-exclude').checked, validated_only: onlyValidated } });\n    name.classList.remove('rolling');\n    name.textContent = `🎉 @${r.winner.pseudo}`;\n    $('d-meta').textContent = `Ticket ${r.winner.ticket_code} · ${r.winner.tickets} ticket(s) sur ${r.winner.total_tickets} · ${r.winner.participants} participant(s)`;\n    loaders.draw();\n  } catch (e) {\n    name.classList.remove('rolling'); name.textContent = '—'; toast(e.message, true);\n  } finally { btn.disabled = false; }\n});\n\n// ---------- Cases & lots ----------\nloaders.cases = async () => {\n  const { cases, icons } = await api('/api/admin/cases');\n  cases.forEach((x) => { rewards[x.day] = x.reward; });\n  $('case-list').replaceChildren(...cases.map((c) => caseEditor(c, icons)));\n};\nfunction caseEditor(c, icons) {\n  const summaryTitle = el('b', { text: c.title || `Case ${c.day}` });\n  const summaryReward = el('small', { text: c.reward ? `🎁 ${c.reward}` : 'Pas de lot' });\n  const field = (label, input, full = true, hint) => el('label', { class: full ? 'full' : '' }, label, hint ? el('span', { class: 'hint', text: hint }) : null, input);\n  const inp = (name, value, extra = {}) => el('input', { name, value: value || '', ...extra });\n\n  const iconSel = el('select', { name: 'icon' }, ...icons.map((i) => el('option', { value: i, text: ICON_LABELS[i] || i, selected: i === c.icon })));\n  const msg = el('textarea', { name: 'message', maxlength: 3000 }); msg.value = c.message;\n  const saved = el('span', { class: 'saved', text: 'Enregistré ✓', hidden: true });\n\n  const form = el('form', {},\n    el('div', { class: 'form-grid' },\n      field('Lot / récompense', inp('reward', c.reward, { maxlength: 300 }), false),\n      field('Décoration de la case', iconSel, false),\n      field('Titre affiché', inp('title', c.title, { maxlength: 120 })),\n      field('Message', msg),\n      field('Image (lien https, optionnel)', inp('image_url', c.image_url, { type: 'url', placeholder: 'https://…' })),\n      field('Lien (optionnel)', inp('link_url', c.link_url, { type: 'url', placeholder: 'https://www.tiktok.com/@…' }), false),\n      field('Texte du bouton du lien', inp('link_label', c.link_label, { maxlength: 60, placeholder: 'Rejoindre le live' }), false)),\n    el('div', { class: 'actions' }, el('button', { class: 'btn-primary', type: 'submit', text: 'Enregistrer la case' }), saved));\n\n  form.addEventListener('submit', async (e) => {\n    e.preventDefault();\n    const body = Object.fromEntries(new FormData(form));\n    try {\n      const r = await api(`/api/admin/cases/${c.day}`, { method: 'PUT', body });\n      summaryTitle.textContent = r.case.title || `Case ${c.day}`;\n      summaryReward.textContent = r.case.reward ? `🎁 ${r.case.reward}` : 'Pas de lot';\n      rewards[c.day] = r.case.reward;\n      saved.hidden = false; setTimeout(() => { saved.hidden = true; }, 2000);\n    } catch (err) { toast(err.message, true); }\n  });\n\n  return el('details', { class: 'case-item' },\n    el('summary', {}, el('span', { class: 'd', text: c.day }), el('span', { class: 't' }, summaryTitle, summaryReward), el('span', { class: 'muted', text: 'Modifier ▾' })),\n    form);\n}\n\n// ---------- Réglages ----------\nloaders.settings = async () => {\n  const { settings } = await api('/api/admin/settings');\n  const f = $('settings-form');\n  for (const [k, v] of Object.entries(settings)) {\n    const input = f.elements[k];\n    if (!input) continue;\n    if (input.type === 'checkbox') input.checked = v === '1'; else input.value = v;\n  }\n};\n$('settings-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const f = e.target;\n  const body = Object.fromEntries(new FormData(f));\n  body.participation_open = f.elements.participation_open.checked;\n  body.music_enabled = f.elements.music_enabled.checked;\n  try {\n    await api('/api/admin/settings', { method: 'PUT', body });\n    $('settings-saved').hidden = false; setTimeout(() => { $('settings-saved').hidden = true; }, 2000);\n  } catch (err) { toast(err.message, true); }\n});\n\n// ---------- Compte ----------\n$('account-form').addEventListener('submit', async (e) => {\n  e.preventDefault();\n  const body = Object.fromEntries(new FormData(e.target));\n  if (body.new_code !== body.confirm) return toast('Les deux nouveaux codes ne correspondent pas.', true);\n  delete body.confirm;\n  try {\n    await api('/api/admin/account', { method: 'PUT', body });\n    alert('Code mis à jour. Reconnecte-toi avec le nouveau code.');\n    location.href = '/admin/login';\n  } catch (err) { toast(err.message, true); }\n});\n\n$('logout').addEventListener('click', async () => {\n  try { await api('/api/admin/logout', { method: 'POST', body: {} }); } finally { location.href = '/admin/login'; }\n});\n\n// ---------- Démarrage ----------\n(async () => {\n  const me = await api('/api/admin/me');\n  CSRF = me.csrf;\n  $('who').textContent = 'Connecté en administrateur';\n  showTab('dashboard');\n})();\n"
 },
 "login.html": {
  "type": "text/html; charset=utf-8",
  "body": "<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex, nofollow\">\n  <title>Connexion administrateur</title>\n  <link rel=\"stylesheet\" href=\"/admin/admin.css\">\n  <script type=\"module\" src=\"/admin/login.js\"></script>\n</head>\n<body class=\"login-page\">\n  <form class=\"login-card\" id=\"login-form\" novalidate>\n    <div class=\"login-logo\">🎄</div>\n    <h1>Espace administrateur</h1>\n    <p class=\"muted\">Accès réservé.</p>\n    <label>Code administrateur\n      <input type=\"password\" id=\"code\" autocomplete=\"current-password\" required autofocus>\n    </label>\n    <p class=\"error\" id=\"error\" role=\"alert\" hidden></p>\n    <button class=\"btn-primary\" type=\"submit\" id=\"submit\">Se connecter</button>\n    <a class=\"back\" href=\"/\">← Retour au calendrier</a>\n  </form>\n</body>\n</html>\n"
 },
 "login.js": {
  "type": "text/javascript; charset=utf-8",
  "body": "const form = document.getElementById('login-form');\nconst err = document.getElementById('error');\n\nform.addEventListener('submit', async (e) => {\n  e.preventDefault();\n  err.hidden = true;\n  const btn = document.getElementById('submit');\n  btn.disabled = true;\n  try {\n    const res = await fetch('/api/admin/login', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ code: document.getElementById('code').value }),\n    });\n    const data = await res.json();\n    if (res.ok) { location.href = '/admin'; return; }\n    err.textContent = data.error || 'Connexion impossible.';\n    err.hidden = false;\n  } catch {\n    err.textContent = 'Problème de connexion au serveur.';\n    err.hidden = false;\n  } finally {\n    btn.disabled = false;\n  }\n});\n"
 }
};
